INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (1, 500, "ペコリーヌの\n満腹ツインおにぎり", 2, "500マイルを獲得する。", 2, 52001, 1, 10, 1, 1, 51001, 0, "ペコリーヌの満腹ツインおにぎり", "ペコリーヌが丹精込めて握った特大おにぎり。\nごはんは命のエネルギーを体現しているらしい。\n普通の人が満腹に感じる量の倍のサイズの中に\n最高級の具を閉じ込めた【美食殿】らしい一品。", "次に振るダイスが2個に増える。出目の合計の数だけ進める。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (3, 500, "コッコロの\nゆるりと休憩サラダ", 2, "500マイルを獲得する。", 30001, 52002, 1, 10, 2, 1, 51002, 0, "コッコロのゆるりと休憩サラダ", "コッコロが皆のことを思って用意したサラダ。\n栄養バランスも考えられたうえに腹持ちもよく\n味だけではなく見た目にも気を配られている。\n冒険への活力を与えてくれる慈愛溢れる一品。", "このターンに振るダイスの目が必ず「1」になる。さらに、次のターン数のカウントをスキップする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "キャルの\n絶品五つ星バーガー", 1, "平凡な未鑑定トレジャーを1個獲得する。", 20004, 52003, 1, 10, 1, 1, 51003, 0, "キャルの絶品五つ星バーガー", "キャルが食べたい物を挟み込んだハンバーガー。\n香ばしいパンとお肉の香りが食欲を刺激する。\n魔物でない素材で作られた、冒険中に食べるには\nゴージャスすぎる一品、とキャルは信じている。", "このターンに振るダイスの目が必ず「5」になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "リリのコツコツ\nまい進かしわ餅", 4, "800マイルを獲得する。", 20001, 52004, 3, 10, 3, 1, 51004, 0, "リリのコツコツまい進かしわ餅", "リリが作った柏餅……の中でも、上手く作れた\n選りすぐりの品。最高の素材を使用した上、\n失敗した分はリリが自分で食べてしまったため\n単価でみるとかなりの高級品となっている。", "ダイスを3回振るまでの間、ダイスの目が必ず「4」になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (4, 500, "クリアの彩り華やか\nバラエティ弁当", 1, "次にダイスを振った際、1マス多く進める。", 1, 52005, 0, 11, 3, 3, 51005, 0, "クリアの彩り華やかバラエティ弁当", "クリアが朝早くから用意した冒険用のお弁当。\nおかずは様々でどれも絶品だが、どんなものが\n入っているかはみんなにも秘密にされているため\n蓋を開けるまでのお楽しみとなっている。", "ランダムなイベントを発生させる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "プレシアの食いしん坊\nぶーぶー肉まん", 4, "800マイルを獲得する。", 20002, 52006, 1, 10, 1, 1, 51006, 0, "プレシアの食いしん坊ぶーぶー肉まん", "プレシアが選び抜いた具を詰め込んだ肉まん。\n彼女の希望で、通常の肉まんの数倍のサイズに\nなっている。味もボリュームも満点でハッピー\n間違いなしですよ♪とは調理担当クリアの談。", "このターンに振るダイスの目が「4・5・6」のみになる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (7, 500, "カヤとイノリの\n食欲倍増ケバブサンド", 3, "福引券を1枚獲得する。", 1, 52007, 2, 10, 1, 1, 51007, 0, "カヤとイノリの食欲倍増ケバブサンド", "カヤとイノリが弁当代わりに持ってきたケバブ。\nイノリ行きつけの店の硬派な味わいで、ギャング\nとしてのやる気が一人3倍、コンビで6倍となり\n下剋上を成し遂げるパワーが湧く……らしい。", "このターンに振るダイスの目を必ず「3」に、次のターンに振るダイスの目を必ず「6」にする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (5, 500, "タマキの金運招く\nレインボーたい焼き", 2, "500マイルを獲得する。", 200, 52008, 0, 10, 2, 2, 51008, 0, "タマキの金運招くレインボーたい焼き", "タマキたちが『ジオ・テオゴニア』に持ち込んだ\nたい焼きの概念が現地の文化と溶け合い生まれた\n魔改造スイーツ。虹色に輝くその甘さは、実に\nランドソルのたい焼きの数倍と言われている。", "次にマイルマスに止まった際の獲得マイルが200%アップする。", 1);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (7, 500, "クローチェの\nフルパワーポテトサラダ", 1, "平凡な未鑑定トレジャーを1個獲得する。", 1, 52009, 2, 10, 2, 1, 51009, 1, "クローチェのフルパワーポテトサラダ", "クローチェがフルパワーで作ったポテトサラダ。\n本来はガレットを作ろうとしたが、うっかり\n握り潰してしまったため、軌道修正して仕上げ\nた一品。経緯はともかく味は非常に美味である。", "[FF7C4E,D62146]【上書き不可】[-]このターンに振るダイスの目を必ず「8」に、次のターンに振るダイスの目を必ず「1」にする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (6, 500, "アヤネとクルミの\n青空ピクニックセット", 2, "500マイルを獲得する。", 1, 52010, 0, 10, 3, 2, 51010, 0, "アヤネとクルミの青空ピクニックセット", "アヤネとクルミが二人で用意した特別なランチ\nバスケット。仲間との冒険への希望が詰まった\nご機嫌な料理の数々で、道中の様々な出来事が\n１ランク上のイベントに感じられるようになる。", "マップ上の「マイルマス」「トレジャーマス」 「ショップマス」のRANKが1つ上がる。効果は対象のマスに計2回止まるまで継続する。", 2);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (7, 500, "リマの不思議な\nスイートアップル", 3, "福引券を1枚獲得する。", 1, 52011, 2, 10, 3, 1, 51011, 0, "リマの不思議なスイートアップル", "リマがネネカにもらったリンゴで作った秘密の\nスイーツ。爽やかな酸味と濃厚な甘さがまるで\n魔法のようなバランスでお互いを引きたてており\n食べた者をたちまち虜にしてしまうという。", "このターンに振るダイスの目を必ず「2」に、次のターンに振るダイスの目を必ず「7」にする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (3, 500, "ニノンのオリジナル\n一二三寿司", 1, "平凡な未鑑定トレジャーを1個獲得する。", 30002, 52012, 1, 10, 2, 1, 51012, 0, "ニノンのオリジナル一二三寿司", "ニノンがジオ・テオゴニアに持ち込んだ特別な\n寿司。厳選された新鮮な魚介を使った逸品だが、\n一部のネタは、寿司のセオリーを逸脱したニノン\n我流のものに仕上がっている。", "このターンに振るダイスの目が「1・2・3」のみになる。さらに、次のターン数のカウントをスキップする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (8, 500, "クレジッタの開運\nお菓子盛り合わせ", 4, "800マイルを獲得する。", 2, 52013, 0, 10, 3, 3, 51013, 0, "クレジッタの開運お菓子盛り合わせ", "クレジッタが考案した、ジオ・テオゴニアで流通\nしているチョコの貨幣の盛り合わせ。一見すると\n金貨を口に入れるおバカさんではあるが、通貨を\n食べるという背徳感が隠し味となっている。", "RANK2のマイルショップを開く。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "リノの\n「時は金時」かき氷", 1, "次にダイスを振った際、1マス多く進める。", 1, 52014, 2, 11, 2, 1, 51014, 0, "リノの「時は金時」かき氷", "可愛い妹がお兄ちゃんのために心を込めて作った\nスペシャルなかき氷。一口食べるとたちどころに\nクールな甘さが精神を研ぎ澄まし、いかなる\nお得をも見逃さない要塞賢母と化すという。", "マイルマスをスキップして移動できる。効果は2ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (1, 500, "シズルの愛情\n盛り盛りハンバーグ", 1, "次にダイスを振った際、1マス多く進める。", 2, 52015, 1, 11, 1, 1, 51015, 0, "シズルの愛情盛り盛りハンバーグ", "お姉ちゃんが弟くんのために心を込めて作った\nスペシャルなハンバーグ。アツアツの肉汁と共に\n溢れんばかりの愛が詰まっており、一口食べる\nだけで、走り回りたくなるような美味しさ。", "次に振るダイスが2個に増える。出目の合計の数だけ進める。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "アオイの疾走\nサンドイッチ", 0, "なし", 20005, 52016, 1, 0, 3, 1, 51016, 0, "アオイの疾走サンドイッチ", "アオイがお弁当として作ったエルフ伝統の野菜\nサンド。一緒についてきてくれる最高の友だち\nの助言により、どんなに深い森の中でも全速力\nで駆け抜けることができるらしい。（アオイ談）", "このターンに振るダイスの目が必ず「6」になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "クウカの緊縛\n触手活け造り", 5, "なし", 1, 52017, 2, 10, 3, 1, 51017, 1, "クウカの緊縛触手活け造り", "数多くのドM妄想をしてきたクウカの中で最近の\nマイブームである触手をモチーフとした活造り。\n新鮮な蛸足が、濃厚なうま味と共に物理的に絡み\n付き身も心も縛りあげられる様な体験ができる。", "[FF7C4E,D62146]【上書き不可】[-]次のターン「移動系カテゴリーの料理」が食べられない代わりに、その場で2000マイルを獲得する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "ランファの世話焼き三昧肉じゃが", 6, "1000マイルを獲得する。", 20006, 52018, 1, 10, 1, 1, 51018, 0, "ランファの世話焼き三昧肉じゃが", "コッコロの指導により料理の腕を上げたランファ\nが手作りした肉じゃが。まだ改善の余地はある\nものの、不器用なランファが誰かのために積み\n重ねた努力を思うととてもおいしく味わえる。", "このターンに振るダイスの目が必ず「3」になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "ワカナの節約腹八分目カレー", 0, "なし", 20007, 52019, 1, 0, 1, 1, 0, 0, "ワカナの節約腹八分目カレー", "バンディ・シスターズの昨夜の夕食カレー。作り\n過ぎて食べきれずにいたものをワカナがお裾分け\nしてくれた。寝かされていたためしっかりと味の\n染みた、極上の二日目カレーとなっている。", "このターンに振るダイスの目が必ず「8」になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "リノの\n「時は金時」かき氷", 1, "次にダイスを振った際、1マス多く進める。", 1, 52020, 2, 11, 2, 2, 51014, 0, "リノの「時は金時」かき氷", "可愛い妹がお兄ちゃんのために心を込めて作った\nスペシャルなかき氷。一口食べるとたちどころに\nクールな甘さが精神を研ぎ澄まし、いかなる\nお得をも見逃さない要塞賢母と化すという。", "マイルマスをスキップして移動できる。効果は2ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "カスミの真実見抜く\nボンボン・ショコラ", 7, "	平凡な未鑑定トレジャーを2個獲得する。", 2, 52021, 3, 10, 3, 2, 51021, 0, "カスミの真実見抜くボンボン・ショコラ", "綺麗な装飾箱に納められたボンボン・ショコラ。\nそのほろ苦さを秘めた濃密な甘さが灰色の脳細胞\nに働きかける時、名探偵の鋭い推理が隠された\n謎を全て白日の下へと晒し、事件を解決へ導く。", "トレジャーマスをスキップして移動できる。効果は3ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "アキノのゲヘニアン\nチキンプレート", 0, "なし", 20008, 52022, 3, 0, 1, 1, 51022, 0, "アキノのゲヘニアンチキンプレート", "アキノがジオ・ゲヘナで仕入れてきたスパイスを\n使用した、お洒落で豪華なチキンプレート。牧場\n特製ヨーグルトソースと奏でる刺激的な味わいは\nまさに二つの世界の奇跡のマリアージュである。", "ダイスを3回振るまでの間、「5と6」の⽬が出る確率が3倍になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (7, 500, "ミミのコロコロ\nお手玉おにぎり", 1, "平凡な未鑑定トレジャーを1個獲得する。", 1, 52023, 2, 10, 1, 1, 51023, 1, "ミミのコロコロお手玉おにぎり", "ミミが、ジオ・ゲヘナで助けてくれたお姉さん達\nのことを思い作ったおにぎり。それぞれ異なる\n味付けがされているが、ミミの願い通りお互いに\nケンカをせず仲良くハーモニーを奏でている。", "[FF7C4E,D62146]【上書き不可】[-]このターンに振るダイスの目を必ず「6」に、次のターンに振るダイスの目を必ず「3」にする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (8, 500, "アユミの隠密\nガトーインビジブル", 3, "次にダイスを振った際、3マス多く進める。", 2, 52024, 0, 11, 3, 3, 51024, 0, "アユミの隠密ガトーインビジブル", "気が付くとリリの手元にあった不思議なお菓子。\n一見普通のケーキだが、内部に様々な具材が\n隠れるように入っている。複雑で重層的な\n味わいを見せる様は、まるで誰かさんのよう。", "RANK2のマイルショップを開く。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "アネモネの\n花爛漫ステーキサラダ", 0, "なし", 3, 52025, 1, 0, 3, 2, 51025, 0, "アネモネの花爛漫ステーキサラダ", "アネモネが世話する秘密の菜園の野菜を使った\nサラダ。栄養を重視するアネモネは草食獣の肉を\n野菜と解釈、当初は野菜の上に肉を置いただけ\nであったが、ネラの指導で盛り付け直された。", "「マイルマス」「トレジャーマス」をスキップして移動できる。効果は1ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (4, 500, "アンナの\n煉獄蕃茄煮混沌卵", 8, "福引券を2枚獲得する。", 1, 52026, 0, 10, 1, 3, 51026, 0, "アンナの煉獄蕃茄煮混沌卵", "ジオ・ゲヘナを探索中の冥姫たちが現地で採取\nしたスパイスで味付けした一皿。赤く煮え滾る\nソースは刺激的かつ非常に奥深い味わいで未知の\n大地の如く冒険者たちをその深奥へと誘う。", "ランダムなイベントを発生させる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "ユイの\n栄養満点まごころ弁当", 0, "なし", 20004, 52027, 2, 0, 3, 1, 51027, 0, "ユイの栄養満点まごころ弁当", "ユイが食べる人のことを考え、心を込めて作った\nお弁当。程よいサイズのお弁当箱に愛情と手間暇\nをたっぷりとかけた極上の料理が詰まっており、\n食べた者の心と胃袋を優しく満たしてくれる。", "ダイスを2回振るまでの間、ダイスの目が必ず「5」になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "リンの\nナッツ入りぐうたらあんパン", 9, "なし", 30003, 52028, 1, 10, 3, 1, 51028, 0, "リンのナッツ入りぐうたらあんパン", "リンからもらった非常食のあんパン。ナッツが\n練り込まれクランチな食感で食べ飽きない。\nゲームのため部屋に引きこもる際のお供であり、\n必要な栄養素が全て賄える完全栄養食、らしい。", "このターンに振るダイスの目が「1・2」のみに\nなる代わりに、その場で福引券を3枚獲得する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (3, 500, "シェフィの\n氷晶煌めく手作りアイス", 0, "なし", 30004, 52029, 1, 0, 2, 1, 51029, 0, "シェフィの氷晶煌めく手作りアイス", "シェフィが自身の魔力の氷を使い作ったアイス。\nペコリーヌにねだられて作ったものだがキャル達\nにも好評である。コッコロ曰くひんやりしている\nのに食べると心が温かくなってきます、との事。", "このターンに振るダイスの目が必ず「2」になる。さらに、次のターン数のカウントをスキップする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (12, 500, "ミソラの\n気まぐれ味噌ラーメン★", 0, "なし", 1, 52030, 3, 0, 1, 3, 51030, 0, "ミソラの気まぐれ味噌ラーメン★", "ミソラが作ったラーメン。適当に言った好きな物\nをランファが憶えていたために、材料を用意され\n仕方なく作ったものだが味はイイコト級の一品。\n美味しそうに食べられるのは嫌いではない様子。", "3ターンの間、すべての「マイルマス」をランク3の「トレジャーマス」に変化させる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "イロハの\n最強クワガタゼリー（人間用）", 0, "なし", 20009, 52031, 1, 0, 3, 1, 51031, 0, "イロハの最強クワガタゼリー（人間用）", "イロハがいつも持ち歩いているカラフルなゼリー\n…なのだがアルケス錬金堂で作られたクワガタ用\n餌ゼリーとそっくりな見た目をしている。甘くて\n美味しいが、人間用か尋ねると目を逸らされる。", "このターンに振るダイスの目が「1・6・6・6・8・8」になる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "グレイスの\n目ん玉飛び出るカップケーキ", 3, "次にダイスを振った際、3マス多く進める。", 4, 52032, 2, 11, 3, 2, 51032, 0, "グレイスの目ん玉飛び出るカップケーキ", "グレイスお手製のカップケーキ。ショッキングな\n見た目に全振り…と思わせて目玉も食べることが\n可能で大変美味…と思わせて一部だけ魂消るほど\n甘い部分がある。原材料は頑なに秘されている。", "料理マスをスキップして移動できる。効果は2ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (8, 500, "ソノの今日は特別ご褒美オムライス", 0, "なし", 3, 52033, 0, 0, 1, 3, 51033, 0, "ソノの今日は特別ご褒美オムライス", "ソノが作ったオムライス。イロハの大好物であり\n家庭の味。普段は面倒くさがりやらないがイロハ\nが良い子の時はケチャップでクワガタを描いて\nあげている。その時は普段より美味しいらしい。", "RANK3のマイルショップを開く。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "ジータの\nグリルド・グラッジチャンク", 1, "平凡な未鑑定トレジャーを1個獲得する。", 1, 52034, 2, 10, 1, 2, 51034, 0, "ジータのグリルド・グラッジチャンク", "そのあまりの美味さと、ほとばしるカロリーから\n悪意の塊、という物騒な名が付けられた肉料理。\nこの肉を集められるかが騎空士としての力量を\n示すため、ジータは大量に集めたがっている。", "マイルマスをスキップして移動できる。効果は2ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (4, 500, "ルイズマリーの\n成功しすぎてるフライ", 10, "貴重な未鑑定トレジャーを1個獲得する。", 1, 52035, 0, 10, 1, 3, 51035, 0, "ルイズマリーの成功しすぎてるフライ", "ルイズマリーが祖母のレシピを忠実に再現した\n最高傑作。精緻な調合と温度管理が生み出す衣と\n身のサクフワは錬金技術の到達点と言われている\nが、ただの料理なのではとの意見も絶えない。", "ランダムなイベントを発生させる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (7, 500, "ホウオウの\n食べる権利をあげます！饅頭", 0, "なし", 1, 52036, 3, 0, 3, 1, 51036, 1, "ホウオウの食べる権利をあげます！饅頭", "ジオ・ゲヘナの空の覇者にして煉華のホウオウが\n己への信仰心を集めるべく作らせたお菓子。中の\n餡はしっとり甘く、上品な味わい。ジオ・ゲヘナ\n銘菓の名を恣にする日も近い、かもしれない。", "[FF7C4E,D62146]【上書き不可】[-]このターンに振るダイスの目を必ず「12」に、次とさらにその次のターンに振るダイスの目を必ず「1」にする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (6, 500, "魔法少女\nナナカちゃんウエハース", 11, "平凡な未鑑定トレジャーを3個獲得する。", 1, 52037, 0, 10, 3, 2, 51037, 0, "魔法少女ナナカちゃんウエハース", "ナナカ考案＆監修のウエハース。おまけシールの\nコレクション性を高くした結果ランドソル中で\n大ブーム…だが肝心の菓子が棄てられる事態に。\n解決のため、王女が自ら口を開いたのだった。", "マップ上の「マイルマス」「トレジャーマス」 「ショップマス」のRANKが1つ上がる。効果は対象のマスに計1回止まるまで継続する。", 1);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (1, 500, "アリサがお届け♪\nリノセウスの包み焼き", 3, "福引券を1枚獲得する。", 2, 52038, 1, 10, 1, 1, 51038, 0, "アリサがお届け♪リノセウスの包み焼き", "アリサ特製の包み焼き。伝承の怪物とよく似た\n魔物を材料にしているため、いつしかその怪物と\n同じ名で呼ばれるようになったという。鋭い鎌と\n火傷に気を付けながら、熱々を召し上がれ。", "次に振るダイスが2個に増える。出目の合計の数だけ進める。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (12, 500, "イリヤの†ブラッディ†\nトマトジュース", 0, "なし", 2, 52039, 2, 0, 2, 3, 51039, 0, "イリヤの†ブラッディ†トマトジュース", "イリヤの愛飲する赤く鮮やかなトマトジュース。\n伝説の吸血鬼に相応しいクオリティを、と求めた\n末に辿り着いた究極の逸品。しかしお値段も相応\nに張るため、特別な時にしか飲めないらしい。", "2ターンの間、すべての「マイルマス」をランク3の「ショップマス」に変化させる。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "マツリの活力源\n～騎士団遠征プレート～", 2, "次にダイスを振った際、2マス多く進める。", 2, 52040, 3, 11, 1, 2, 51040, 0, "マツリの活力源～騎士団遠征プレート～", "【王宮騎士団】遠征時の定番メニューにマツリが\nアレンジを加え調理したプレート。苦手な野菜を\nなくしてお肉倍増を目論んだのが配膳前にバレ、\nジュンの指導できちんと野菜も入れさせられた。", "トレジャーマスをスキップして移動できる。効果は3ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (7, 500, "ヴァンピィちゃんの\nさいきょースープ", 1, "平凡な未鑑定トレジャーを1個獲得する。", 1, 52041, 2, 10, 1, 1, 51041, 1, "ヴァンピィちゃんのさいきょースープ", "ヴァンピィがよく振舞ってくれる特製スープ。\nどうやら家庭料理のようで、素朴な味わいが\n人々を郷愁へと誘う。昔誰かと並んで一緒に\n肉団子を作ったような…とはヴァンピィの言葉。", "[FF7C4E,D62146]【上書き不可】[-]このターンに振るダイスの目を必ず「7」に、次のターンに振るダイスの目を必ず「2」にする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "アイラのみんなで\n飲みたい赤麦しゅわ", 0, "なし", 20002, 52042, 2, 0, 2, 1, 51042, 0, "アイラのみんなで飲みたい赤麦しゅわ", "アイラが愛する赤麦しゅわ。彼女の熱い要望で\n酩酊感ゼロの子供向けも生産開始した。曰くこの\n美味しさを広めるためとのことだが、本当は単に\n老若男女皆で楽しく飲みたいだけかもしれない。", "ダイスを2回振るまでの間、出る目が「4・5・6」のみになる", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (2, 500, "レイの釣りたて\n鮮魚七輪塩焼き", 12, "なし", 1, 52043, 2, 10, 1, 1, 51043, 1, "レイの釣りたて鮮魚七輪塩焼き", "レイが釣った魚の塩焼き。試行錯誤の末に理想の\n塩と火の加減にたどり着いた。調理は真剣勝負で\n釣りと同様、己の心との戦いだという。レイも\n時々、集中しすぎて仲間に心配されているとか。", "[FF7C4E,D62146]【上書き不可】[-]次のターン「移動系カテゴリーの料理」が食べられない代わりに、その場で貴重な未鑑定トレジャーを3個獲得する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (3, 500, "ユキノ製ごろっと果実の\nかちこち氷菓子", 3, "福引券を1枚獲得する。", 30002, 52044, 1, 10, 2, 1, 51044, 0, "ユキノ製ごろっと果実のかちこち氷菓子", "ユキノが偶然生み出した、青果実のアイスバー。\n元は誤って凍らせたものだが爽やかな味が好評で\nなんと久遠氷河を代表する手土産に。伸び続ける\n売り上げに本人が一番溶けそうになっている。", "このターンに振るダイスの目が「1・2・3」のみになる。さらに、次のターン数のカウントをスキップする。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "サレンの思い出ぎっしり\n焼きそばパン", 4, "800マイルを獲得する。", 5, 52045, 3, 10, 3, 2, 51045, 0, "サレンの思い出ぎっしり焼きそばパン", "サレンが作った思い出の焼きそばパン。どっしり\nしたボリュームある炭水化物×炭水化物の信頼感\nで皆を笑顔に変える。専用の皿に盛り付けたら見\n栄えも十分。カロリーは気にしないのがお作法。", "「ショップマス」「ミニゲームマス」「イベントマス」をスキップして移動できる。効果は3ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (9, 500, "アラクネの肉マシマシマシ炒め\n野菜入り", 0, "なし", 1, 52046, 3, 0, 1, 2, 51046, 0, "アラクネの肉マシマシマシ炒め野菜入り", "アラクネが初めて覚えた料理。周囲の人々が自分\nより小さいのは小食が理由と思っているらしく、\nたくさん食べて大きくなってほしいという優しさ\nから、超ボリュームなデカ盛り仕様となった。", "マイルマスをスキップして移動できる。効果は3ターンの間継続する。", 0);
INSERT INTO `v1_8e8b243441897fe2c8422cb853572932b425f0053c2cb7647cf4f281975cba3f` VALUES (1, 500, "シナツの極うな重\n韋駄天仕上げ", 1, "平凡な未鑑定トレジャーを1個獲得する。", 2, 52047, 1, 10, 1, 1, 51047, 0, "シナツの極うな重　韋駄天仕上げ", "胃に入れば何でも同じ、が信条のシナツが自分で\n釣った鰻で拵えたうな重。レイの協力のもと練習\nを重ね、見た目も味も合格点に到達した。一番\n苦労したのは調理場を破壊しない力加減だとか。", "次に振るダイスが2個に増える。出目の合計の数だけ進める。", 0);
